<?php
declare(strict_types=1);
namespace Moves\Services\Talk;
use Moves\Boot\Connection;
use PDO;
final class TalkInboundService{
 public function receiveWhatsApp(array $payload):int{$external=mb_substr(trim((string)($payload['external_id']??'')),0,191);$phone=preg_replace('/\D+/','',(string)($payload['from']??''))??'';$body=mb_substr(trim((string)($payload['body']??'')),0,4000);if($external===''||$phone==='')throw new \RuntimeException('Mensagem WhatsApp inválida.');$pdo=Connection::getInstance();$dup=$pdo->prepare("SELECT id FROM talk_messages WHERE external_id=:external LIMIT 1");$dup->execute(['external'=>$external]);if($dup->fetchColumn())return 0;$pdo->beginTransaction();try{$q=$pdo->prepare("SELECT id FROM talk_contacts WHERE phone=:phone LIMIT 1");$q->execute(['phone'=>$phone]);$contactId=(int)($q->fetchColumn()?:0);if($contactId===0){$name=mb_substr(trim((string)($payload['push_name']??'')),0,160);$i=$pdo->prepare("INSERT INTO talk_contacts(name,phone,external_id,status) VALUES(:name,:phone,:external,'active')");$i->execute(['name'=>$name!==''?$name:null,'phone'=>$phone,'external'=>$phone]);$contactId=(int)$pdo->lastInsertId();}$q=$pdo->prepare("SELECT id FROM talk_conversations WHERE contact_id=:contact AND channel='whatsapp' ORDER BY id DESC LIMIT 1");$q->execute(['contact'=>$contactId]);$conversationId=(int)($q->fetchColumn()?:0);if($conversationId===0){$i=$pdo->prepare("INSERT INTO talk_conversations(contact_id,channel,status,last_message_at) VALUES(:contact,'whatsapp','open',NOW())");$i->execute(['contact'=>$contactId]);$conversationId=(int)$pdo->lastInsertId();}$q=$pdo->prepare("SELECT id,status FROM talk_tickets WHERE conversation_id=:conversation ORDER BY id DESC LIMIT 1");$q->execute(['conversation'=>$conversationId]);$ticket=$q->fetch(PDO::FETCH_ASSOC);$ticketId=(int)($ticket['id']??0);if($ticketId===0||($ticket['status']??'')==='closed'){$protocol='TALK-'.date('Ymd').'-'.str_pad((string)random_int(1,999999),6,'0',STR_PAD_LEFT);$i=$pdo->prepare("INSERT INTO talk_tickets(conversation_id,protocol,status,priority,source,created_at,updated_at,last_activity_at) VALUES(:conversation,:protocol,'queued','normal','whatsapp',NOW(),NOW(),NOW())");$i->execute(['conversation'=>$conversationId,'protocol'=>$protocol]);$ticketId=(int)$pdo->lastInsertId();}$i=$pdo->prepare("INSERT INTO talk_messages(conversation_id,ticket_id,sender_type,external_id,direction,type,body,metadata,sent_at) VALUES(:conversation,:ticket,'contact',:external,'inbound',:type,:body,:metadata,NOW())");$i->execute(['conversation'=>$conversationId,'ticket'=>$ticketId,'external'=>$external,'type'=>mb_substr((string)($payload['type']??'text'),0,50),'body'=>$body,'metadata'=>json_encode(['channel'=>'whatsapp','push_name'=>$payload['push_name']??null],JSON_UNESCAPED_UNICODE)]);$pdo->prepare("UPDATE talk_conversations SET status='open',last_message_at=NOW(),updated_at=NOW() WHERE id=:id")->execute(['id'=>$conversationId]);$pdo->prepare("UPDATE talk_tickets SET last_activity_at=NOW(),updated_at=NOW() WHERE id=:id")->execute(['id'=>$ticketId]);$pdo->commit();return $ticketId;}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
}